parameters.jsCode:
// Tomar la respuesta cruda de la IA (ajusta el nombre de campo según tu output real)
const rawResponse = $input.first().json.content.parts[0].text

let analisisIA;
if (typeof rawResponse === "object") {
  analisisIA = rawResponse;
} else {
  let texto = String(rawResponse).trim();
  texto = texto.replace(/^```json\s*/i, "").replace(/```$/, "").trim();
  try {
    analisisIA = JSON.parse(texto);
  } catch (err) {
    return [{
      json: {
        ...$json,
        error_parseo: true,
        mensaje_error: "No se pudo interpretar la respuesta de la IA como JSON.",
        respuesta_cruda: texto
      }
    }];
  }
}

return [{
  json: {
    ...$json,
    experiencia_anios: analisisIA.experiencia_anios,
    habilidades: analisisIA.habilidades,
    nivel_educativo: analisisIA.nivel_educativo,
    compatibilidad: analisisIA.compatibilidad,
    observaciones: analisisIA.observaciones,
    preguntas_sugeridas: analisisIA.preguntas_sugeridas
  }
}];

