const requisitos = {
  "Desarrollador Backend Junior": {
    tecnologias: ["Java", "Spring Boot", "SQL", "Git", "REST API"],
    experiencia_minima: 1,

    nivel_educativo_minimo: "Técnico"
  },
  "Desarrollador Frontend": {
    tecnologias: ["HTML", "CSS", "JavaScript", "React", "Git"],
    experiencia_minima: 1,
    nivel_educativo_minimo: "Técnico"
  },
  "Analista de Datos": {
    tecnologias: ["SQL", "Power BI", "Excel avanzado", "Python"],
    experiencia_minima: 2,
    nivel_educativo_minimo: "Profesional"
  },
  "DevOps / Ingeniero de Infraestructura": {
    tecnologias: ["Docker", "AWS", "Linux", "CI/CD", "Git"],
    experiencia_minima: 2,
    nivel_educativo_minimo: "Técnico"
  },
  "Desarrollador Full Stack": {
    tecnologias: ["JavaScript", "Node.js", "React", "SQL", "Git", "REST API"],
    experiencia_minima: 3,
    nivel_educativo_minimo: "Profesional"
  }
};

const vacante = $('Normalizar').first().json.Vacante;
const req = requisitos[vacante];

return {
  json: {
    ...$json,
    requisitos_texto: req
      ? `Tecnologías requeridas: ${req.tecnologias.join(", ")}. Experiencia mínima: ${req.experiencia_minima} año(s). Nivel educativo mínimo: ${req.nivel_educativo_minimo}.`
      : "Vacante no encontrada en el catálogo de requisitos."
  }
};

// Modo: Run Once for All Items

const items = $input.all();

if (items.length === 0) {
  return [{
    json: {
      mensaje: "No hay candidatos pendientes de revisión en este momento."
    }
  }];
}

let mensaje = `📋 Candidatos pendientes de revisión (${items.length})\n\n`;

items.forEach((item, index) => {
  const c = item.json;
  mensaje += `${index + 1}. ${c.nombre || "Sin nombre"}\n`;
  mensaje += `   ID: ${c.id_candidato || "N/A"}\n`;
  mensaje += `   Vacante: ${c.vacante || "N/A"}\n`;
  mensaje += `   Compatibilidad: ${c.score_compatibilidad || "N/A"}%\n\n`;
});

return [{
  json: {
    mensaje: mensaje.trim()
  }
}];

